package sources

import (
	"encoding/json"
	"os"
	"testing"

	"github.com/agentstation/starmap/pkg/catalogs"
)

func TestCaptureLegacyObservationReceipt(t *testing.T) {
	observation := receiptObservation(t)
	payload, err := catalogs.EncodeCatalogPayload(observation.Catalog)
	if err != nil {
		t.Fatal(err)
	}
	fixture := struct {
		Observation Observation     `json:"observation"`
		Payload     json.RawMessage `json:"payload"`
	}{observation, payload}
	raw, err := json.MarshalIndent(fixture, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile("testdata/legacy-observation-receipt.json", append(raw, '\n'), 0o644); err != nil {
		t.Fatal(err)
	}
}
